const commits = $input.first().json || [];
const prs = $input.last().json || [];

// Filter PRs merged this week
const oneWeekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
const mergedPRs = prs.filter(pr => {
  return pr.merged_at && new Date(pr.merged_at) >= oneWeekAgo;
});

// Group commits by author
const byAuthor = {};
commits.forEach(c => {
  const author = c.commit?.author?.name || 'unknown';
  if (!byAuthor[author]) byAuthor[author] = [];
  byAuthor[author].push({
    message: c.commit?.message?.split('\n')[0] || '',
    date: c.commit?.author?.date || ''
  });
});

// Build summary input
const summary = {
  week: new Date().toISOString().split('T')[0],
  totalCommits: commits.length,
  mergedPRs: mergedPRs.length,
  authors: Object.keys(byAuthor).length,
  commitsByAuthor: byAuthor,
  prTitles: mergedPRs.map(pr => `#${pr.number}: ${pr.title}`),
  topContributors: Object.entries(byAuthor)
    .sort((a, b) => b[1].length - a[1].length)
    .slice(0, 5)
    .map(([name, c]) => ({ name, commits: c.length }))
};

return [{ json: summary }];

